int maxSumOfK(int[] a, int k) {
    int sum = 0, best = Integer.MIN_VALUE;
    for (int r = 0; r < a.length; r++) {
        sum += a[r];
        if (r >= k) sum -= a[r - k];
        if (r >= k - 1) best = Math.max(best, sum);
    }
    return best;
}

